'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const key='damda-ui-preferences-v1';
const initial=DamDaModel.empty();
let saved={};try{saved=JSON.parse(localStorage.getItem(key)||'{}');}catch{}
let model=structuredClone(initial),collection=[],prefs={theme:'light',language:'ko',motion:'full',...saved},customPresets=[];
let signed=false,tab='profile',filter='전체',query='',page=1,preset='business',side='front',angle={x:0,y:0},lastFocus=null;
let toastTimer;const t=(ko,en)=>prefs.language==='en'?en:ko;
const icons={card:'<rect x="3" y="5" width="18" height="14"/><path d="M7 10h5m-5 4h9"/>',book:'<path d="M5 3h14v18H5zM9 3v18m4-12h3m-3 4h3"/>',grid:'<path d="M3 3h7v7H3zm11 0h7v7h-7zM3 14h7v7H3zm11 0h7v7h-7z"/>',settings:'<path d="M4 7h16M4 17h16M8 4v6m8 4v6"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',out:'<path d="M13 4H4v16h9m1-12 5 4-5 4m-5-4h10"/>',plus:'<path d="M12 4v16M4 12h16"/>',check:'<path d="m5 12 4 4L19 6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',image:'<rect x="3" y="3" width="18" height="18"/><path d="m3 17 6-6 5 5 3-3 4 4M15 7h2"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',rotate:'<path d="M20 8a9 9 0 1 0 1 7M20 3v6h-6"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',sun:'<path d="M12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2"/><circle cx="12" cy="12" r="4"/>',lock:'<rect x="5" y="10" width="14" height="11"/><path d="M8 10V6a4 4 0 0 1 8 0v4m-4 8v-4"/>'};
const icon=n=>'<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="square" aria-hidden="true">'+(icons[n]||icons.card)+'</svg>';
function notify(msg){const el=$('#toast');el.textContent=msg;try{if(el.showPopover&&!el.matches(':popover-open'))el.showPopover();}catch{}el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>{el.classList.remove('visible');setTimeout(()=>{if(!el.classList.contains('visible'))try{el.hidePopover?.();}catch{}},250);},3000);}
function persist(){}
function applyPrefs(){document.documentElement.lang=prefs.language;document.documentElement.dataset.theme=prefs.theme==='system'?(matchMedia('(prefers-color-scheme:dark)').matches?'dark':'light'):prefs.theme;document.documentElement.dataset.motion=prefs.motion;}
function brand(){return '<a class="brand" href="#home" aria-label="DamDa home"><img src="mark.svg" alt=""><span>DamDa<span class="brand-dot">.</span></span></a>';}
function route(){return ['home','book','templates'].includes(location.hash.slice(1))?location.hash.slice(1):'home';}
function settingButton(){return '<button class="icon-button" data-action="settings" aria-label="'+t('설정','Settings')+'" title="'+t('설정','Settings')+'">'+icon('settings')+'</button>';}
function login(){return "";}

function shell(content){const page=route();return '<div class="shell"><aside class="sidebar">'+brand()+'<span class="sidebar-caption">PERSONAL WORKSPACE</span><nav aria-label="'+t('메인 메뉴','Main navigation')+'">'+[['home','card','내 명함','My card','01'],['book','book','명함함','Collection','02'],['templates','grid','디자인 갤러리','Gallery','03'],['settings','settings','설정','Settings','04']].map(([id,i,ko,en,num])=>'<a href="#'+id+'" class="nav-link '+(page===id?'active':'')+'" '+(page===id?'aria-current="page"':'')+(id==='settings'?' data-nav-settings':'')+' title="'+t(ko,en)+'">'+icon(i)+'<span>'+t(ko,en)+'</span><small>'+num+'</small></a>').join('')+'</nav><div class="sidebar-bottom"><div class="lab-label"><span>DAMDA STUDIO</span><small>YOUR PERSONAL SPACE</small></div><div class="sidebar-account"><span class="account-mark">↗</span><div><b>'+esc(model.name||t('내 워크스페이스','My workspace'))+'</b><small>MY ACCOUNT</small></div><button class="icon-button" data-action="logout" aria-label="'+t('로그아웃','Log out')+'" title="'+t('로그아웃','Log out')+'">'+icon('out')+'</button></div></div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb">WORKSPACE <span>/</span> <b>'+t(page==='book'?'명함함':page==='templates'?'디자인 갤러리':'내 명함',page==='book'?'Collection':page==='templates'?'Design gallery':'My card')+'</b></div><div class="topbar-actions"><span class="save-indicator">'+icon('check')+'<span id="save-state">'+t('계정에 저장됨','Saved to account')+'</span></span></div></header><main id="main">'+content+'</main><footer class="workspace-footer"><span>DamDa <b>DAMDA STUDIO</b></span><span>'+t('나를 담는 새로운 방식.','A new way to introduce yourself.')+'</span><span>2026 / 01</span></footer></div></div>';}
const colorNames={paper:['페이퍼','Paper'],ink:['잉크','Ink'],lime:['라임','Lime'],clay:['클레이','Clay']};
const fields=[['role','직업','Role'],['company','회사','Company'],['email','이메일','Email'],['phone','전화번호','Phone'],['website','웹사이트','Website'],['instagram','Instagram','Instagram']];
function headline(kicker,title,sub,action=''){return '<div class="page-heading"><div><div class="eyebrow">'+kicker+'</div><h1>'+title+'</h1><p>'+sub+'</p></div>'+action+'</div>';}
function input(label,prop,value,max=80){return '<label>'+label+'<input data-model="'+prop+'" value="'+esc(value)+'" maxlength="'+max+'"></label>';}
function choices(prop,current,values){return '<div class="choices">'+values.map(([v,l])=>'<label><input type="radio" name="'+prop+'" data-choice="'+prop+'" value="'+v+'" '+(v===current?'checked':'')+'><span>'+l+'</span></label>').join('')+'</div>';}
function profilePanel(){return '<div class="panel-section"><div class="section-label"><h3>'+t('기본 정보','Identity')+'</h3><span>01</span></div><div class="two-inputs">'+input(t('이름','Name'),'name',model.name,30)+input(t('닉네임','Nickname'),'nickname',model.nickname,30)+'</div><fieldset><legend>'+t('명함에 표시할 이름','Display name')+'</legend>'+choices('identity',model.identity,[['name',t('이름','Name')],['nickname',t('닉네임','Nickname')]])+'</fieldset><label class="check-row"><input type="checkbox" data-model="showName" '+(model.showName?'checked':'')+'>'+t('명함에 이름 표시','Show name on card')+'</label></div><div class="panel-section"><div class="section-label"><h3>'+t('연락처와 소개','Contact & details')+'</h3><span>02</span></div><p class="help">'+t('체크한 항목만 명함에 표시됩니다.','Only checked details appear on your card.')+'</p>'+fields.map(([id,ko,en])=>'<div class="detail-row"><label class="field-toggle"><input type="checkbox" data-visible="'+id+'" aria-label="'+t(ko,en)+' '+t('표시','visibility')+'" '+(model.visible.includes(id)?'checked':'')+'><span>'+t(ko,en)+'</span></label><input data-model="'+id+'" aria-label="'+t(ko,en)+'" value="'+esc(model[id])+'" maxlength="100"></div>').join('')+model.custom.map((f,i)=>'<div class="detail-row custom-row"><label class="field-toggle"><input type="checkbox" data-custom-visible="'+i+'" '+(f.selected?'checked':'')+'><span>'+esc(f.label)+'</span></label><input data-custom="'+i+'" value="'+esc(f.value)+'" maxlength="100" aria-label="'+esc(f.label)+'"><button class="icon-button" data-remove-field="'+i+'" aria-label="'+t('항목 삭제','Remove field')+'">'+icon('close')+'</button></div>').join('')+'<form id="custom-form" class="inline-form"><input name="label" maxlength="20" required placeholder="'+t('새 항목 이름','New field name')+'" aria-label="'+t('새 항목 이름','New field name')+'"><button class="icon-button" title="'+t('항목 추가','Add field')+'" aria-label="'+t('항목 추가','Add field')+'">'+icon('plus')+'</button></form></div>';}
function designPanel(){return '<div class="panel-section"><div class="section-label"><h3>'+t('카드 컬러','Card color')+'</h3><span>01</span></div><div class="color-options">'+Object.entries(colorNames).map(([id,names])=>'<button class="color-option '+(model.color===id?'selected':'')+'" data-color="'+id+'" aria-pressed="'+(model.color===id)+'"><span class="color-chip '+id+'">'+(model.color===id?icon('check'):'')+'</span>'+t(...names)+'</button>').join('')+'</div></div><div class="panel-section"><div class="section-label"><h3>'+t('레이아웃','Layout')+'</h3><span>02</span></div>'+choices('layout',model.layout,[['editorial',t('에디토리얼','Editorial')],['minimal',t('미니멀','Minimal')]])+'</div><div class="panel-section"><div class="section-label"><h3>'+t('프로필 사진','Profile image')+'</h3><span>03</span></div><div class="photo-editor"><div class="photo-placeholder">'+(model.photo?'<img src="'+esc(model.photo)+'" alt="'+t('프로필','Profile')+'">':icon('image'))+'</div><div><button class="button small" data-action="upload">'+t('사진 업로드','Upload image')+'</button><button class="text-button" data-action="remove-photo">'+t('사진 삭제','Remove')+'</button><small class="help">JPG, PNG, WEBP · MAX 5MB</small></div></div><input type="file" id="photo-file" accept="image/png,image/jpeg,image/webp" hidden><fieldset><legend>'+t('사진 모양','Image shape')+'</legend>'+choices('photoShape',model.photoShape,[['square',t('사각형','Square')],['portrait',t('세로형','Portrait')]])+'</fieldset><fieldset><legend>'+t('사진 크기','Image size')+'</legend>'+choices('photoSize',model.photoSize,[['small',t('작게','Small')],['medium',t('보통','Medium')],['large',t('크게','Large')]])+'</fieldset></div>';}
function backPanel(){return '<div class="panel-section"><div class="section-label"><h3>'+t('뒷면 메시지','Reverse message')+'</h3><span>01</span></div><label>'+t('헤드라인','Headline')+'<textarea data-model="backTitle" maxlength="60" rows="2">'+esc(model.backTitle)+'</textarea></label><label>'+t('소개 문구','Personal note')+'<textarea data-model="backMessage" maxlength="240" rows="4">'+esc(model.backMessage)+'</textarea></label></div><div class="panel-section"><div class="section-label"><h3>'+t('뒷면 스타일','Reverse style')+'</h3><span>02</span></div><fieldset><legend>'+t('배경 컬러','Background')+'</legend>'+choices('backColor',model.backColor,Object.entries(colorNames).map(([id,n])=>[id,t(...n)]))+'</fieldset><fieldset><legend>'+t('패턴','Pattern')+'</legend>'+choices('backPattern',model.backPattern,[['plain',t('없음','None')],['grid',t('그리드','Grid')],['stripes',t('스트라이프','Stripes')]])+'</fieldset><button class="button full" data-action="back">'+t('뒷면 확인하기','View reverse')+icon('arrow')+'</button></div>';}
const edges=[-.36,-.18,0,.18,.36].map(z=>'<i class="card-edge" style="--z:'+z+'cqw" aria-hidden="true"></i>').join('');
function cardMarkup(data=model,interactive=true){const shown=fields.filter(([id])=>data.visible.includes(id)&&data[id]),name=data.identity==='nickname'?data.nickname:data.name;return '<div class="card-object '+(interactive?'interactive':'')+'" '+(interactive?'tabindex="0" role="group" aria-label="'+t('3D 명함. 드래그 또는 방향키로 회전','3D card. Drag or use arrow keys to rotate')+'"':'')+'><div class="card-rotator" '+(interactive?'style="transform:rotateX('+angle.x+'deg) rotateY('+angle.y+'deg)"':'')+'>'+edges+'<div class="business-card front '+data.color+' '+data.layout+'"><div class="card-brand">DamDa<span>PERSONAL IDENTITY / 01</span></div><div class="card-main"><div><h2>'+esc(data.showName?name:'')+'</h2>'+shown.filter(([id])=>['role','company'].includes(id)).map(([id])=>'<p class="card-role">'+esc(data[id])+'</p>').join('')+'</div>'+(data.photo?'<img class="card-photo '+data.photoShape+' '+data.photoSize+'" src="'+esc(data.photo)+'" alt="'+t('프로필 사진','Profile photo')+'">':'<div class="card-glyph" aria-hidden="true"><i></i><i></i><i></i></div>')+'</div><div class="card-bottom"><div class="card-details">'+shown.filter(([id])=>!['role','company'].includes(id)).map(([id])=>'<span>'+esc(data[id])+'</span>').join('')+(data.custom||[]).filter(f=>f.selected&&f.value).map(f=>'<span>'+esc(f.label)+' · '+esc(f.value)+'</span>').join('')+'</div><span class="card-index">LET’S<br>CONNECT ↗</span></div></div><div class="business-card reverse '+data.backColor+' pattern-'+data.backPattern+'"><div class="card-brand">DamDa<span>THE OTHER SIDE / 02</span></div><h2>'+esc(data.backTitle)+'</h2><p>'+esc(data.backMessage)+'</p><div class="reverse-bottom"><span>MADE FOR THE NEXT CONNECTION.</span><b>↗</b></div></div></div></div>';}
function presets(){return '<div class="preset-bar"><span class="eyebrow">'+t('공개 정보 프리셋','VISIBILITY PRESET')+'</span><div class="preset-options">'+[['business','비즈니스','Business'],['personal','퍼스널','Personal'],['minimal','미니멀','Minimal'],...customPresets.map((p,i)=>['custom-'+i,p.name,p.name])].map(([id,ko,en])=>'<button data-preset="'+id+'" aria-pressed="'+(preset===id)+'" class="'+(preset===id?'active':'')+'">'+esc(t(ko,en))+'</button>').join('')+'<button data-action="preset-manage" aria-label="'+t('프리셋 관리','Manage presets')+'" title="'+t('프리셋 관리','Manage presets')+'">'+icon('settings')+'</button><button data-action="preset-add" aria-label="'+t('프리셋 저장','Save preset')+'" title="'+t('프리셋 저장','Save preset')+'">'+icon('plus')+'</button></div></div>';}
function home(){return headline('MAKE YOUR FIRST IMPRESSION',t('나다운 연결의 시작.','Make your introduction.'),t('정보는 간결하게. 당신은 선명하게.','Less noise. More you.'),'<button class="button primary" data-action="export">'+icon('download')+t('명함 내보내기','Export card')+'</button>')+'<div class="editor-layout"><section class="editor-panel" aria-label="'+t('명함 편집','Card editor')+'"><div class="editor-tabs" role="tablist">'+[['profile','프로필','Profile'],['design','디자인','Design'],['back','뒷면','Reverse']].map(([id,ko,en],i)=>'<button id="tab-'+id+'" role="tab" aria-selected="'+(tab===id)+'" aria-controls="editor-content" tabindex="'+(tab===id?'0':'-1')+'" data-tab="'+id+'"><small>0'+(i+1)+'</small>'+t(ko,en)+'</button>').join('')+'</div><div id="editor-content" role="tabpanel" aria-labelledby="tab-'+tab+'">'+(tab==='profile'?profilePanel():tab==='design'?designPanel():backPanel())+'</div><div class="editor-foot">'+icon('lock')+t('선택한 정보만 표시됩니다.','Only selected details are displayed.')+'</div></section><section class="preview-panel" aria-label="'+t('명함 미리보기','Card preview')+'">'+presets()+'<div class="preview-stage"><div class="stage-label"><span>LIVE PREVIEW</span><span>01 — DIGITAL CARD</span></div><div id="live-card">'+cardMarkup()+'</div><div class="stage-caption"><span>'+t('드래그하거나 터치해 돌려보세요','Drag or swipe to rotate')+'</span><span>3D VIEW</span></div></div><div class="preview-toolbar"><div class="segmented"><button data-action="front" aria-pressed="'+(side==='front')+'">'+t('앞면','Front')+'</button><button data-action="back" aria-pressed="'+(side==='back')+'">'+t('뒷면','Reverse')+'</button></div><button class="text-button" data-action="rotate-reset">'+icon('rotate')+t('회전 초기화','Reset view')+'</button></div><div class="preview-summary"><div><span class="eyebrow">READY FOR YOUR NEXT HELLO</span><h3>'+t('한 장에 담긴, 당신의 가능성.','One card. New possibilities.')+'</h3><p>'+t('앞면의 첫인상부터 뒷면의 작은 메시지까지.','From a first impression to a personal note.')+'</p></div><button class="icon-button" data-action="export" aria-label="'+t('명함 내보내기','Export card')+'">'+icon('arrow')+'</button></div><div class="local-note"><span class="tiny-block"></span>'+t('변경 사항은 내 계정에 자동 저장됩니다.','Changes are saved automatically to your account.')+'</div></section></div>';}
function book(){return headline('PEOPLE, NOT JUST CONTACTS',t('좋은 만남을 모으다.','Keep good company.'),t('기억하고 싶은 사람들, 다시 이어질 이야기.','Good people. Conversations worth continuing.'),'<button class="button primary" data-action="save-card">'+icon('plus')+t('내 명함 보관','Keep my card')+'</button>')+'<div class="collection-controls"><div class="filter-tabs">'+['전체',...new Set(collection.map(c=>c.group))].map(v=>'<button data-filter="'+esc(v)+'" aria-pressed="'+(filter===v)+'">'+(v==='전체'?t('전체','All'):esc(v))+' <small>'+collection.filter(c=>v==='전체'||c.group===v).length+'</small></button>').join('')+'</div><label class="search">'+icon('search')+'<input id="search" placeholder="'+t('이름, 회사 검색','Search name or company')+'" aria-label="'+t('명함 검색','Search cards')+'" value="'+esc(query)+'"></label></div><div id="collection-grid" class="collection-grid">'+collectionItems()+'</div><nav id="collection-pager" class="collection-pager" aria-label="'+t('페이지','Pages')+'">'+pager()+'</nav><p class="local-note">'+t('계정에 보관한 명함입니다. 다른 기기에서도 확인할 수 있습니다.','Your saved cards are available on other devices.')+'</p>';}
const pageSize=6;
function filtered(){return collection.filter(c=>(filter==='전체'||c.group===filter)&&(c.name+' '+c.company+' '+c.role).toLowerCase().includes(query.toLowerCase()));}
function pageCount(){return Math.max(1,Math.ceil(filtered().length/pageSize));}
function pager(){const n=pageCount();page=Math.min(Math.max(1,page),n);if(n<2)return '';return '<button class="text-button" data-page="'+(page-1)+'" '+(page===1?'disabled':'')+' aria-label="'+t('이전 페이지','Previous page')+'">←</button>'+Array.from({length:n},(_,i)=>'<button data-page="'+(i+1)+'" aria-pressed="'+(page===i+1)+'" aria-label="'+t('페이지 ','Page ')+(i+1)+'">'+(i+1)+'</button>').join('')+'<button class="text-button" data-page="'+(page+1)+'" '+(page===n?'disabled':'')+' aria-label="'+t('다음 페이지','Next page')+'">→</button>';}
function refreshCollection(keepScroll=false){const grid=$('#collection-grid'),y=window.scrollY;grid.style.minHeight=keepScroll?grid.offsetHeight+'px':'';grid.innerHTML=collectionItems();$('#collection-pager').innerHTML=pager();observeCards();if(keepScroll)window.scrollTo(0,y);}
function collectionItems(){const all=filtered();page=Math.min(Math.max(1,page),pageCount());const start=(page-1)*pageSize,cards=all.slice(start,start+pageSize);return cards.length?cards.map((c,j)=>{const i=start+j;return '<article class="collection-item"><button class="collection-preview" data-open-card="'+esc(c.id)+'" aria-label="'+esc(c.name)+' '+t('명함 보기','View card')+'">'+cardMarkup(c,false)+'</button><div class="collection-info"><div><span class="eyebrow">'+esc(c.group)+' / '+String(i+1).padStart(2,'0')+'</span><h3>'+esc(c.name)+'</h3><p>'+esc(c.company)+'</p></div><button class="icon-button" data-open-card="'+esc(c.id)+'" aria-label="'+esc(c.name)+' '+t('상세 보기','Details')+'">'+icon('arrow')+'</button></div></article>';}).join(''):'<div class="empty"><span>—</span><h3>'+t('검색 결과가 없습니다.','No cards found.')+'</h3><p>'+t('다른 이름이나 회사를 검색해 보세요.','Try another name or company.')+'</p></div>';}
function gallery(){return headline('A FRAME FOR YOUR IDENTITY',t('당신을 담는 네 가지 시선.','Four ways to be you.'),t('색과 여백으로 완성하는 나만의 첫인상.','Define your first impression through color and space.'))+'<div class="gallery-grid">'+Object.entries(colorNames).map(([id,n],i)=>'<article class="gallery-item"><div class="gallery-card">'+cardMarkup({...model,color:id},false)+'</div><div class="gallery-meta"><div><span class="eyebrow">COLLECTION 0'+(i+1)+'</span><h2>'+t(...n)+'</h2><p>'+[t('절제된 여백, 선명한 인상.','Quiet space. Clear intent.'),t('깊이 있는 대비, 단단한 존재감.','A confident contrast.'),t('새로운 감각, 유연한 가능성.','A fresh perspective.'),t('따뜻한 시선, 감각적인 균형.','Warmth in balance.')][i]+'</p></div><button class="button" data-template="'+id+'">'+t('적용하기','Apply')+icon('arrow')+'</button></div></article>').join('')+'</div>';}

function fitCardText(){for(const el of document.querySelectorAll('.business-card .card-main h2,.business-card .card-role,.business-card .card-details,.business-card.reverse h2,.business-card.reverse p')){el.style.fontSize='';let size=parseFloat(getComputedStyle(el).fontSize);for(let i=0;i<40&&(el.scrollHeight>el.clientHeight+1||el.scrollWidth>el.clientWidth+1);i++){size*=.94;el.style.fontSize=size+'px';}}}
const cardResizeObserver=new ResizeObserver(()=>fitCardText());
function observeCards(){cardResizeObserver.disconnect();document.querySelectorAll('.card-object').forEach(el=>cardResizeObserver.observe(el));requestAnimationFrame(fitCardText);}
function render(){applyPrefs();$('#app').innerHTML=signed?shell(route()==='book'?book():route()==='templates'?gallery():home()):login();observeCards();}
function updateCard(){persist();if($('#live-card'))$('#live-card').innerHTML=cardMarkup();observeCards();}
function openDialog(content,type=''){lastFocus=document.activeElement;const d=$('#dialog');d.className='dialog '+type;d.innerHTML='<div class="dialog-close"><button class="icon-button" data-action="close-dialog" aria-label="'+t('닫기','Close')+'">'+icon('close')+'</button></div>'+content;if(!d.open)d.showModal();observeCards();}
function closeDialog(){ $('#dialog').close();lastFocus?.isConnected&&lastFocus.focus();}
function settings(){openDialog('<div class="eyebrow">YOUR WORKSPACE, YOUR RULES</div><h2>'+t('환경 설정','Workspace settings')+'</h2><p class="muted">'+t('당신에게 가장 편안한 작업 환경.','Find your own working rhythm.')+'</p><fieldset><legend>'+t('화면 모드','Appearance')+'</legend>'+choices('theme',prefs.theme,[['light',t('라이트','Light')],['dark',t('다크','Dark')],['system',t('시스템','System')]])+'</fieldset><fieldset><legend>'+t('언어','Language')+'</legend>'+choices('language',prefs.language,[['ko','한국어'],['en','English']])+'</fieldset><fieldset><legend>'+t('애니메이션','Motion')+'</legend>'+choices('motion',prefs.motion,[['full',t('기본','Standard')],['reduced',t('최소화','Reduced')]])+'</fieldset><div class="settings-note"><span class="eyebrow">DAMDA STUDIO</span><p>'+t('화면 설정은 이 기기에 저장됩니다. 프로필과 명함함은 로그인한 계정에 보관됩니다.','Appearance stays on this device. Your profile and cards are saved to your account.')+'</p></div>','settings-dialog');}
async function exportDialog(){}

function applyPreset(id){preset=id;if(id.startsWith('custom-')){const p=customPresets[Number(id.slice(7))];if(p)model.visible=[...p.visible];}else model.visible=id==='business'?['role','company','email','website']:id==='personal'?['email','phone','instagram']:['role','email'];persist();render();}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function vcf(data=model){download(new Blob([DamDaExport.vcard(DamDaModel.snapshot(data))],{type:'text/vcard;charset=utf-8'}),'DamDa-contact.vcf');}
async function exportPNG(back=false,data=model){
 await document.fonts.ready;
 const canvas=document.createElement('canvas');canvas.width=1440;canvas.height=800;const ctx=canvas.getContext('2d');ctx.scale(1.6,1.6);
 const colors={paper:['#f8f7f2','#202622'],ink:['#202622','#f8f7f2'],lime:['#c3ef62','#202622'],clay:['#e3c3b2','#332822'],blue:['#243c84','#ffffff'],mint:['#e7f6f1','#203d35']},[bg,ink]=colors[back?data.backColor:data.color];ctx.fillStyle=bg;ctx.fillRect(0,0,900,500);ctx.fillStyle=ink;
 const font=(size,bold=false)=>{ctx.font=(bold?'600 ':'')+size+'px LabSans, sans-serif';};
 const one=(text,x,y,width,size,bold=false)=>{font(size,bold);const measured=ctx.measureText(text).width;if(measured>width)font(size*width/measured,bold);ctx.fillText(text,x,y);};
 const block=(text,x,y,width,height,size)=>{let lines=[];for(let attempt=0;attempt<50;attempt++){font(size);lines=[];for(const p of text.split('\n')){let line='';for(const c of p){if(ctx.measureText(line+c).width>width&&line){lines.push(line);line='';}line+=c;}lines.push(line);}if(lines.length*size*1.4<=height)break;size*=.94;}font(size);lines.forEach((line,i)=>ctx.fillText(line,x,y+size+i*size*1.4));};
 one('DamDa',50,60,240,28,true);one(back?'THE OTHER SIDE / 02':'PERSONAL IDENTITY / 01',630,58,220,10);
 if(back){if(data.backPattern!=='plain'){ctx.globalAlpha=.07;for(let x=0;x<900;x+=44){ctx.fillRect(x,0,1,500);if(data.backPattern==='grid')ctx.fillRect(0,x,900,1);}ctx.globalAlpha=1;}block(data.backTitle,50,115,800,160,46);block(data.backMessage,50,295,800,130,18);one('MADE FOR THE NEXT CONNECTION.',50,455,700,10);one('↗',820,460,40,40);}
 else{one(data.showName?(data.identity==='nickname'?data.nickname:data.name):'',50,190,620,60,true);let y=228;for(const id of ['role','company'])if(data.visible.includes(id)&&data[id]){one(data[id],50,y,590,18);y+=27;}if(data.photo){const img=new Image();img.src=data.photo;await img.decode();const w={small:80,medium:110,large:140}[data.photoSize],h=data.photoShape==='portrait'?w*1.25:w;ctx.save();ctx.beginPath();const x=850-w;if(data.photoShape==='circle')ctx.ellipse(x+w/2,120+h/2,w/2,h/2,0,0,Math.PI*2);else if(data.photoShape==='rounded')ctx.roundRect(x,120,w,h,w*.2);else ctx.rect(x,120,w,h);ctx.clip();const ratio=Math.max(w/img.width,h/img.height),sw=w/ratio,sh=h/ratio;ctx.drawImage(img,(img.width-sw)/2,(img.height-sh)/2,sw,sh,x,120,w,h);ctx.restore();}if(data.layout!=='minimal'){ctx.strokeStyle=ink;ctx.beginPath();ctx.moveTo(50,322);ctx.lineTo(850,322);ctx.stroke();}const details=fields.filter(([id])=>!['role','company'].includes(id)&&data.visible.includes(id)&&data[id]).map(([id])=>data[id]).concat(data.custom.filter(f=>f.selected&&f.value).map(f=>f.label+' · '+f.value));const columns=details.length>3?2:1;details.forEach((text,i)=>one(text,50+(i%columns)*335,350+Math.floor(i/columns)*24,columns===2?310:650,15));one('LET’S CONNECT ↗',745,455,105,10);}
 canvas.toBlob(blob=>{if(blob)download(blob,'DamDa-'+(back?'reverse':'front')+'.png');},'image/png');
}
function saveCard(){collection.unshift({...structuredClone(model),id:crypto.randomUUID(),group:t('내 명함','My cards')});persist();notify(t('명함함에 보관했습니다.','Saved to your collection.'));if(route()==='book')render();}
function setSide(value){side=value;angle={x:0,y:value==='back'?180:0};const rot=$('#live-card .card-rotator');if(rot)rot.style.transform='rotateY('+angle.y+'deg)';$$('.segmented [data-action]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.action===value));}
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target;if(f.id==='custom-form'){const label=f.elements.label.value.trim();if(!label)return;if(model.custom.length>=5){notify(t('추가 항목은 최대 5개입니다.','Up to 5 extra fields.'));return;}model.custom.push({label,value:'',selected:true});persist();render();}if(f.id==='preset-form'){customPresets.push({name:f.elements.name.value.trim(),visible:[...model.visible]});preset='custom-'+(customPresets.length-1);persist();closeDialog();render();}});
document.addEventListener('input',e=>{const el=e.target;if(el.dataset.model&&el.type!=='checkbox'){model[el.dataset.model]=el.value;updateCard();}if(el.dataset.custom!==undefined){model.custom[+el.dataset.custom].value=el.value;updateCard();}if(el.id==='search'){query=el.value;page=1;refreshCollection();}});
document.addEventListener('change',async e=>{const el=e.target;if(el.dataset.model&&el.type==='checkbox'){model[el.dataset.model]=el.checked;updateCard();}if(el.dataset.visible){model.visible=el.checked?[...new Set([...model.visible,el.dataset.visible])]:model.visible.filter(v=>v!==el.dataset.visible);preset='';updateCard();$$('[data-preset]').forEach(b=>{b.classList.remove('active');b.setAttribute('aria-pressed','false');});}if(el.dataset.customVisible!==undefined){model.custom[+el.dataset.customVisible].selected=el.checked;updateCard();}if(el.dataset.choice){const prop=el.dataset.choice;if(['theme','language','motion'].includes(prop)){prefs[prop]=el.value;persist();render();settings();}else{model[prop]=el.value;updateCard();}}if(el.id==='photo-file'&&el.files[0]){const file=el.files[0];if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>5*1024*1024){notify(t('5MB 이하 JPG, PNG, WEBP를 선택해 주세요.','Choose a JPG, PNG or WEBP under 5MB.'));return;}try{const bitmap=await createImageBitmap(file),c=document.createElement('canvas');const scale=Math.min(1,600/Math.max(bitmap.width,bitmap.height));c.width=bitmap.width*scale;c.height=bitmap.height*scale;c.getContext('2d').drawImage(bitmap,0,0,c.width,c.height);bitmap.close();model.photo=c.toDataURL('image/webp',.85);persist();render();}catch{notify(t('이미지를 읽지 못했습니다.','Could not load image.'));}}});
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;
 if(b.dataset.tab){tab=b.dataset.tab;render();$('#tab-'+tab)?.focus();return;}if(b.dataset.color){model.color=b.dataset.color;persist();render();return;}if(b.dataset.preset){applyPreset(b.dataset.preset);return;}if(b.dataset.template){model.color=b.dataset.template;tab='design';persist();location.hash='home';render();notify(t('디자인을 적용했습니다.','Design applied.'));return;}if(b.dataset.filter){filter=b.dataset.filter;page=1;render();return;}if(b.dataset.page){page=+b.dataset.page;refreshCollection(true);return;}if(b.dataset.removeField!==undefined){model.custom.splice(+b.dataset.removeField,1);persist();render();return;}if(b.dataset.openCard){const c=collection.find(c=>c.id===b.dataset.openCard);if(!c)return;openDialog('<div class="eyebrow">YOUR COLLECTION</div><h2>'+esc(c.name)+'</h2><div class="detail-card">'+cardMarkup(c,false)+'</div><label>'+t('분류','Category')+'<input id="card-group" maxlength="30" value="'+esc(c.group)+'"></label><div class="dialog-actions"><button class="button" data-update-group="'+esc(c.id)+'">'+t('분류 저장','Save category')+'</button><button class="text-button danger" data-delete-card="'+esc(c.id)+'">'+t('명함 삭제','Delete card')+'</button></div>');return;}if(b.dataset.updateGroup){const c=collection.find(c=>c.id===b.dataset.updateGroup);if(c)c.group=$('#card-group').value.trim()||t('미분류','Unsorted');persist();closeDialog();filter='전체';render();return;}if(b.dataset.removePreset!==undefined){customPresets.splice(+b.dataset.removePreset,1);preset='';persist();closeDialog();render();return;}if(b.dataset.updatePreset!==undefined){const i=+b.dataset.updatePreset;customPresets[i].name=document.getElementById('preset-name-'+i).value.trim()||customPresets[i].name;persist();notify(t('프리셋 이름을 변경했습니다.','Preset renamed.'));return;}if(b.dataset.deleteCard){collection=collection.filter(c=>c.id!==b.dataset.deleteCard);persist();closeDialog();render();return;}
 const action=b.dataset.action;if(!action)return;
 if(action==='preset-manage')openDialog('<div class="eyebrow">VISIBILITY PRESETS</div><h2>'+t('프리셋 관리','Manage presets')+'</h2><p class="muted">'+t('기본 프리셋은 유지됩니다. 사용자 프리셋의 이름을 바꾸거나 삭제할 수 있습니다.','Default presets stay available. Rename or remove custom presets.')+'</p>'+customPresets.map((p,i)=>'<div class="preset-edit"><label>'+t('프리셋 이름','Preset name')+'<input id="preset-name-'+i+'" value="'+esc(p.name)+'" maxlength="20"></label><button class="button" data-update-preset="'+i+'">'+t('변경','Rename')+'</button><button class="text-button danger" data-remove-preset="'+i+'">'+t('삭제','Delete')+'</button></div>').join('')+(!customPresets.length?'<p class="local-note">'+t('+ 버튼으로 사용자 프리셋을 먼저 저장해 보세요.','Save a custom preset with the + button first.')+'</p>':''));if(action==='settings')settings();if(action==='close-dialog')closeDialog();
 
 if(action==='show-password'){const el=b.closest('form').elements.password;el.type=el.type==='password'?'text':'password';b.textContent=el.type==='password'?t('보기','Show'):t('숨기기','Hide');}
 if(['front','back','rotate-reset'].includes(action))setSide(action==='back'?'back':'front');if(action==='upload')$('#photo-file').click();if(action==='remove-photo'){model.photo='';persist();render();}
 if(action==='export')exportDialog();if(action==='download-front')exportPNG();if(action==='download-back')exportPNG(true);if(action==='download-vcf')vcf();if(action==='save-card')saveCard();
  if(action==='preset-add'){if(customPresets.length>=6){notify(t('사용자 프리셋은 최대 6개입니다.','Up to 6 custom presets.'));return;}openDialog('<div class="eyebrow">YOUR OWN COMBINATION</div><h2>'+t('프리셋 저장','Save a preset')+'</h2><p class="muted">'+t('현재 선택한 공개 항목을 저장합니다.','Save the current visibility selection.')+'</p><form id="preset-form"><label>'+t('프리셋 이름','Preset name')+'<input name="name" required maxlength="20"></label><button class="button primary full">'+t('저장하기','Save preset')+'</button></form>');}
});
document.addEventListener('click',e=>{const a=e.target.closest('a[data-nav-settings]');if(!a)return;e.preventDefault();settings();});
let drag=null;
document.addEventListener('pointerdown',e=>{const el=e.target.closest('.card-object.interactive');if(!el||(e.pointerType==='mouse'&&e.button!==0))return;e.preventDefault();drag={el,id:e.pointerId,x:e.clientX,y:e.clientY,rx:angle.x,ry:angle.y};el.setPointerCapture(e.pointerId);el.classList.add('dragging');});
document.addEventListener('pointermove',e=>{if(!drag||drag.id!==e.pointerId)return;angle.x=Math.max(-60,Math.min(60,drag.rx-(e.clientY-drag.y)*.4));angle.y=drag.ry+(e.clientX-drag.x)*.6;drag.el.querySelector('.card-rotator').style.transform='rotateX('+angle.x+'deg) rotateY('+angle.y+'deg)';});
for(const ev of ['pointerup','pointercancel','lostpointercapture'])document.addEventListener(ev,e=>{if(drag?.id===e.pointerId){const {el}=drag;el.classList.remove('dragging');drag=null;angle={x:0,y:Math.round(angle.y/180)*180};side=Math.abs(angle.y/180)%2?'back':'front';el.querySelector('.card-rotator').style.transform='rotateX(0deg) rotateY('+angle.y+'deg)';$$('.segmented [data-action]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.action===side));}});
document.addEventListener('keydown',e=>{const tabButton=e.target.closest('[role="tab"]');if(tabButton&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const tabs=['profile','design','back'];tab=e.key==='Home'?'profile':e.key==='End'?'back':tabs[(tabs.indexOf(tab)+(e.key==='ArrowRight'?1:2))%3];render();$('#tab-'+tab).focus();}const el=e.target.closest('.card-object.interactive');if(!el||!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Home'].includes(e.key))return;e.preventDefault();if(e.key==='Home'){setSide('front');return;}if(e.key==='ArrowLeft')angle.y-=15;if(e.key==='ArrowRight')angle.y+=15;if(e.key==='ArrowUp')angle.x=Math.max(-60,angle.x-15);if(e.key==='ArrowDown')angle.x=Math.min(60,angle.x+15);el.querySelector('.card-rotator').style.transform='rotateX('+angle.x+'deg) rotateY('+angle.y+'deg)';});
$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog();}});
$('#dialog').addEventListener('close',()=>lastFocus?.isConnected&&lastFocus.focus());
matchMedia('(prefers-color-scheme:dark)').addEventListener('change',()=>{if(prefs.theme==='system')applyPrefs();});
document.fonts.ready.then(fitCardText);
window.addEventListener('hashchange',()=>{if($('#dialog').open)closeDialog();render();window.scrollTo(0,0);});